from openpyxl import load_workbook

wb = load_workbook("budget.xlsx", data_only=False)
for ws in wb.worksheets:
    print(f"=== Sheet: {ws.title} (dims={ws.dimensions}) ===")
    for row in ws.iter_rows():
        vals = []
        for c in row:
            if c.value is not None:
                vals.append(f"{c.coordinate}={c.value!r}")
        if vals:
            print(" | ".join(vals))
    print()

import zipfile
import re
from xml.etree import ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_index(ref):
    m = re.match(r"([A-Z]+)", ref)
    n = 0
    for ch in m.group(1):
        n = n * 26 + (ord(ch) - 64)
    return n - 1

def row_index(ref):
    return int(re.search(r"(\d+)", ref).group(1)) - 1

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()

    # Map sheet names -> worksheet xml paths
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.attrib["Id"]: r.attrib["Target"] for r in rels}
    sheets = []
    for sh in wb.find("m:sheets", NS):
        rid = sh.attrib["{%s}id" % NS["r"]]
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        sheets.append((sh.attrib["name"], target))

    # Shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    for sheet_name, path in sheets:
        root = ET.fromstring(z.read(path))
        rows = {}
        for c in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
            ref = c.attrib.get("r")
            t = c.attrib.get("t")
            v = c.find("m:v", NS)
            isel = c.find("m:is", NS)
            if v is None and isel is None:
                continue
            if isel is not None:
                val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            elif t == "s":
                val = shared[int(v.text)]
            elif t == "str" or t == "inlineStr":
                val = v.text
            elif t == "b":
                val = v.text == "1"
            else:
                val = float(v.text) if v.text is not None else None
            rows[(row_index(ref), col_index(ref))] = val
        print(f"=== Sheet: {sheet_name} ===")
        if rows:
            max_r = max(r for r, c in rows)
            max_c = max(c for r, c in rows)
            for r in range(max_r + 1):
                cells = []
                for c in range(max_c + 1):
                    if (r, c) in rows:
                        cells.append(str(rows[(r, c)]))
                    else:
                        cells.append("")
                print(f"R{r+1}: " + " | ".join(cells))
        print()

